package cn.paletale.companion;
import com.google.gson.*;
import com.sun.net.httpserver.HttpServer;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.Button;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class WorldSearchClientTest {
 static Object field(Object o,String key){return WorldClientGameTest.field(o,key);}static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static String tooltip(Button button){try{var f=net.minecraft.client.gui.components.AbstractWidget.class.getDeclaredField("tooltip");f.setAccessible(true);var holder=(net.minecraft.client.gui.components.WidgetTooltipHolder)f.get(button);var tip=holder.get();if(tip==null)return null;var m=net.minecraft.client.gui.components.Tooltip.class.getDeclaredField("message");m.setAccessible(true);return ((net.minecraft.network.chat.Component)m.get(tip)).getString();}catch(Exception e){throw new AssertionError(e);}}
 static Map<String,String> query(URI uri){var result=new HashMap<String,String>();for(String pair:Objects.toString(uri.getRawQuery(),"").split("&")){var parts=pair.split("=",2);result.put(parts[0],parts.length>1?URLDecoder.decode(parts[1],StandardCharsets.UTF_8):"");}return result;}
 static void run(ClientGameTestContext context)throws Exception{
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var workers=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor();server.setExecutor(workers);
  server.createContext("/api/",ex->{var q=query(ex.getRequestURI());String path=ex.getRequestURI().getPath();var root=new JsonObject();int status=200;
   if(path.endsWith("/online")){int page=Integer.parseInt(q.getOrDefault("page","1"));root.addProperty("version",1);int total=q.getOrDefault("view","all").equals("archives")?11:q.getOrDefault("view","all").equals("mod")?3:73;root.addProperty("total",total);var rows=new JsonArray();for(int i=(page-1)*24;i<Math.min(total,page*24);i++){var row=new JsonObject();row.addProperty("name","OnlinePlayerVeryLong"+i);row.addProperty("eligible",false);rows.add(row);}root.add("players",rows);}
   else if(path.endsWith("/catalog")){root=WorldDensityClientTest.payload(ex.getRequestURI());if(!root.getAsJsonArray("items").isEmpty()){var item=root.getAsJsonArray("items").get(0).getAsJsonObject();item.addProperty("minSell",99999999.99);item.addProperty("maxBuy",123456789.12);}}
   else if(path.endsWith("/search")){String kind=q.get("kind");int size=Integer.parseInt(q.get("size")),page=Integer.parseInt(q.get("matchPage")),total=kind.equals("玩家")?73:kind.equals("领地")?35:kind.equals("国家")?3:0;root.addProperty("version",1);root.addProperty("kind",kind);root.addProperty("size",size);root.addProperty("page",page);root.addProperty("total",total);var rows=new JsonArray();for(int i=(page-1)*size;i<Math.min(total,page*size);i++){var row=new JsonObject();row.addProperty("kind",kind);row.addProperty("name",kind.equals("玩家")?"xiaochenLongPlayer"+i:kind+"样例"+i);row.addProperty("count",i);row.addProperty("href","/smc/"+(kind.equals("玩家")?"players":kind.equals("领地")?"lands":"nations")+"/"+i);rows.add(row);}root.add("entries",rows);}
   else status=404;byte[] bytes=root.toString().getBytes(StandardCharsets.UTF_8);ex.getResponseHeaders().set("Content-Type","application/json");ex.sendResponseHeaders(status,bytes.length);try(var out=ex.getResponseBody()){out.write(bytes);}
  });server.start();var api=new MarketApi(URI.create("http://127.0.0.1:"+server.getAddress().getPort()));
  try{
   context.runOnClient(c->{c.getWindow().setWindowed(1920,1080);c.options.guiScale().set(2);c.resizeDisplay();c.setScreen(new WorldEntityScreen(null,api,"online","all"));});var names=new LinkedHashSet<String>();
   for(int page=1;page<=3;page++){context.waitFor(c->field(c.screen,"catalog")!=null&&!((Boolean)field(c.screen,"loading")),600);final int current=page;context.runOnClient(c->{int capacity=(Integer)field(c.screen,"perPage");require(capacity==36,"Viewport holds 36 players rather than fixed 24");var cards=c.screen.children().stream().filter(b->b instanceof ArchiveCardButton).map(b->(ArchiveCardButton)b).toList();require(cards.size()==(current<3?36:1),"Each full online page fills every grid position");for(var card:cards)require(names.add(card.entry.name()),"No duplicated online player across API boundary");require(cards.stream().anyMatch(card->card.entry.name().equals(tooltip(card))),"truncated online player card shows full name");});if(page==1){context.waitFor(c->((Map<?,?>)field(c.screen,"onlineCounts")).size()==3,600);context.runOnClient(c->{var counts=(Map<?,?>)field(c.screen,"onlineCounts");require(counts.get("全部在线").equals(73)&&counts.get("档案在线").equals(11)&&counts.get("模组在线").equals(3),"All three online tabs show their own counts");});context.takeScreenshot("smc-v21-online-counts");}if(page<3)context.clickScreenButton("下一页");}require(names.size()==73,"All online players reachable without gaps");
   context.runOnClient(c->{var screen=new WorldScreen(null,api);WorldClientGameTest.field(screen,"text","");WorldClientGameTest.field(screen,"selectedItem","");WorldClientGameTest.field(screen,"page",1);c.setScreen(screen);});context.waitFor(c->field(c.screen,"result")!=null&&!((Boolean)field(c.screen,"loading")),600);context.takeScreenshot("smc-v20-two-price-lines");
   context.runOnClient(c->{var screen=new WorldScreen(null,api);WorldClientGameTest.field(screen,"text","样例");WorldClientGameTest.field(screen,"selectedItem","");WorldClientGameTest.field(screen,"page",1);c.setScreen(screen);});context.waitFor(c->field(c.screen,"result")!=null&&!((Boolean)field(c.screen,"loading")),600);
   context.waitFor(c->{var groups=(List<?>)field(field(c.screen,"searchSections"),"groups");return groups.size()==4&&groups.stream().noneMatch(g->(Boolean)field(g,"busy"));},600);
   context.runOnClient(c->{var card=c.screen.children().stream().filter(b->b instanceof Button button&&button.getMessage().getString().equals("xiaochenLongPlayer0")).map(b->(Button)b).findFirst().orElseThrow();require("xiaochenLongPlayer0".equals(tooltip(card)),"truncated search player card exposes full tooltip");});
   var tipPoint=context.computeOnClient(c->{var screen=(WindowScreen)c.screen;var card=c.screen.children().stream().filter(b->b instanceof Button button&&button.getMessage().getString().equals("xiaochenLongPlayer0")).map(b->(Button)b).findFirst().orElseThrow();return new int[]{(int)((screen.winX+(card.getX()+8)*screen.windowScale)*c.getWindow().getGuiScale()),(int)((screen.winY+(card.getY()+8)*screen.windowScale)*c.getWindow().getGuiScale())};});context.getInput().setCursorPos(tipPoint[0],tipPoint[1]);context.waitTicks(20);context.takeScreenshot("smc-beta4-search-full-name-tooltip");
   context.runOnClient(c->{var groups=(List<?>)field(field(c.screen,"searchSections"),"groups");require((Integer)field(groups.getFirst(),"total")==73,"Search exposes all player matches beyond the old first twelve");require((Integer)field(c.screen,"searchHeight")>((net.minecraft.client.gui.screens.Screen)c.screen).height-116,"Search sections scroll without truncating other kinds");var next=c.screen.children().stream().filter(b->b instanceof Button a&&a.getY()==70&&a.getMessage().getString().equals("下一页")).map(b->(Button)b).findFirst().orElseThrow();next.onPress(new net.minecraft.client.input.KeyEvent(257,0,0));});
   context.waitFor(c->((List<?>)field(field(c.screen,"searchSections"),"groups")).stream().noneMatch(g->(Boolean)field(g,"busy")),600);
   context.runOnClient(c->{var groups=(List<?>)field(field(c.screen,"searchSections"),"groups");require((Integer)field(groups.getFirst(),"page")==2&&(Integer)field(groups.get(1),"page")==1,"Player and land pagination are independent");});context.takeScreenshot("smc-v20-search-players-page2");
   context.runOnClient(c->{var screen=(WorldScreen)c.screen;for(int i=0;i<12;i++)screen.mouseScrolled(screen.winX+(Integer)field(screen,"bodyX")+10,screen.winY+100,0,-10);});context.takeScreenshot("smc-v20-search-scrolled-sections");
  }finally{context.runOnClient(c->c.setScreen(null));server.stop(0);workers.shutdownNow();}
  if(Boolean.getBoolean("paletale.test.liveLocalV20")){
   var local=new MarketApi(URI.create("http://localhost:3000"));context.runOnClient(c->{var screen=new WorldScreen(null,local);WorldClientGameTest.field(screen,"text","a");WorldClientGameTest.field(screen,"selectedItem","");WorldClientGameTest.field(screen,"page",1);c.setScreen(screen);});
   context.waitFor(c->field(c.screen,"result")!=null&&!((Boolean)field(c.screen,"loading")),1200);
   context.waitFor(c->{var groups=(List<?>)field(field(c.screen,"searchSections"),"groups");return !groups.isEmpty()&&groups.stream().noneMatch(g->(Boolean)field(g,"busy"));},1200);
   context.runOnClient(c->{var groups=(List<?>)field(field(c.screen,"searchSections"),"groups");require((Integer)field(groups.getFirst(),"total")>12&&((String)field(groups.getFirst(),"error")).isEmpty(),"Actual local API returns complete public player search to the native client");});context.takeScreenshot("smc-v20-live-local-search");
   context.runOnClient(c->{var s=(WorldScreen)c.screen;for(int i=0;i<20;i++)s.mouseScrolled(s.winX+(Integer)field(s,"bodyX")+10,s.winY+100,0,-1);});context.takeScreenshot("smc-v20-live-local-item-section");context.runOnClient(c->c.setScreen(null));
  }
 }
}
